{"command":"cat <<'EOF' > main.go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"text/template"
	"github.com/hairyhenderson/gomplate/math"
	"github.com/hairyhenderson/gomplate/net"
	"github.com/spf13/pflag"
)

func main() {
	var in string
	var file string
	var out string
	var datasources []string
	var contexts []string
	var leftDelim string
	var rightDelim string
	var inputDir string
	var outputDir string
	var outputMap string

	pflag.StringVarP(&in, "in", "i", "", "Template string to process")
	pflag.StringVarP(&file, "file", "f", "-", "Template file to process")
	pflag.StringVarP(&out, "out", "o", "-", "output file name")
	pflag.StringArrayVarP(&datasources, "datasource", "d", nil, "datasource in alias=URL form")
	pflag.StringArrayVarP(&contexts, "context", "c", nil, "pre-load a datasource into the context")
	pflag.StringVar(&leftDelim, "left-delim", "{{", "override the default left-delimiter")
	pflag.StringVar(&rightDelim, "right-delim", "}}", "override the default right-delimiter")
	pflag.StringVar(&inputDir, "input-dir", "", "directory which is examined recursively for templates")
	pflag.StringVar(&outputDir, "output-dir", ".", "directory to store the processed templates")
	pflag.StringVar(&outputMap, "output-map", "", "Template string to map the input file to an output path")
    pflag.BoolP("help", "h", false, "help for gomplate")
    pflag.BoolP("version", "v", false, "version for gomplate")

	pflag.Parse()

    if v, _ := pflag.CommandLine.GetBool("version"); v {
        fmt.Println("gomplate version 0.0.0")
        return
    }

	dsMap := make(map[string]string)
	for _, dsStr := range datasources {
		parts := strings.SplitN(dsStr, "=", 2)
		if len(parts) == 2 {
			dsMap[parts[0]] = parts[1]
		}
	}

	ctxMap := make(map[string]interface{})
    envMap := make(map[string]string)
    for _, e := range os.Environ() {
        parts := strings.SplitN(e, "=", 2)
        if len(parts) == 2 {
            envMap[parts[0]] = parts[1]
        }
    }
    ctxMap["Env"] = envMap

	for _, cStr := range contexts {
		parts := strings.SplitN(cStr, "=", 2)
		if len(parts) == 2 {
			alias := parts[0]
			url := parts[1]
			data, err := readDatasource(url)
			if err == nil {
                parsedData := parseData(url, data)
				if alias == "." {
					if m, ok := parsedData.(map[string]interface{}); ok {
						for k, v := range m {
							ctxMap[k] = v
						}
					}
				} else {
					ctxMap[alias] = parsedData
				}
			}
		}
	}

	funcMap := template.FuncMap{
		"ds": func(alias string) (interface{}, error) {
			url, ok := dsMap[alias]
			if !ok {
				return nil, fmt.Errorf("datasource '%s' not found", alias)
			}
			data, err := readDatasource(url)
			if err != nil {
				return nil, err
			}
			return parseData(url, data), nil
		},
		"json": func(in string) (interface{}, error) {
			var res interface{}
			err := json.Unmarshal([]byte(in), &res)
			return res, err
		},
		"toUpper": strings.ToUpper,
		"toLower": strings.ToLower,
		"strings.ToUpper": strings.ToUpper,
		"strings.ToLower": strings.ToLower,
		"strings.ReplaceAll": strings.ReplaceAll,
		"strings.TrimSpace": strings.TrimSpace,
		"strings.Split": strings.Split,
		"strings.Join": strings.Join,
		"add": func(n ...int64) int64 { return math.AddInt(n...) },
		"mul": func(n ...int64) int64 { return math.MulInt(n...) },
		"math.Add": func(n ...int64) int64 { return math.AddInt(n...) },
		"math.Mul": func(n ...int64) int64 { return math.MulInt(n...) },
		"math.Seq": math.Seq,
        "seq": func(args ...int64) []int64 {
            var start, end, step int64 = 1, 0, 1
            switch len(args) {
            case 1:
                end = args[0]
            case 2:
                start = args[0]
                end = args[1]
            case 3:
                start = args[0]
                end = args[1]
                step = args[2]
            }
            return math.Seq(start, end, step)
        },
        "net.LookupIP": func(name string) (string, error) {
            return net.LookupIP(context.Background(), name)
        },
	}

	if inputDir != "" {
		// Handle input directory
        // ...
	} else {
		var tmplSource string
		if in != "" {
			tmplSource = in
		} else {
			var r io.Reader
			if file == "-" {
				r = os.Stdin
			} else {
				f, err := os.Open(file)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
					os.Exit(1)
				}
				defer f.Close()
				r = f
			}
			b, err := ioutil.ReadAll(r)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error reading: %v\n", err)
				os.Exit(1)
			}
			tmplSource = string(b)
		}

		tmpl, err := template.New("tmpl").Delims(leftDelim, rightDelim).Funcs(funcMap).Parse(tmplSource)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing template: %v\n", err)
			os.Exit(1)
		}

		var w io.Writer
		if out == "-" {
			w = os.Stdout
		} else {
			f, err := os.Create(out)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error creating output file: %v\n", err)
				os.Exit(1)
			}
			defer f.Close()
			w = f
		}

		err = tmpl.Execute(w, ctxMap)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error executing template: %v\n", err)
			os.Exit(1)
		}
	}
}

func readDatasource(url string) ([]byte, error) {
	if strings.HasPrefix(url, "http://") || strings.HasPrefix(url, "https://") {
		resp, err := http.Get(url)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		return ioutil.ReadAll(resp.Body)
	}
    if strings.HasPrefix(url, "env:") {
        varName := strings.TrimPrefix(url, "env:")
        return []byte(os.Getenv(varName)), nil
    }
    if strings.HasPrefix(url, "env:///") {
        varName := strings.TrimPrefix(url, "env:///")
        return []byte(os.Getenv(varName)), nil
    }
	// Assume file
    path := url
    if strings.HasPrefix(url, "file://") {
        path = strings.TrimPrefix(url, "file://")
    }
	return ioutil.ReadFile(path)
}

func parseData(url string, data []byte) interface{} {
	if strings.HasSuffix(url, ".json") {
		var res interface{}
		json.Unmarshal(data, &res)
		return res
	}
	return string(data)
}
EOF
"}

