	out = "-"
	outputDir = "."
	missingKey = "error"

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if i+1 < len(args) {
			switch arg {
			case "-i", "--in": i++; in = args[i]
			case "-f", "--file": i++; file = args[i]
			case "-o", "--out": i++; out = args[i]
			case "-d", "--datasource": i++; datasources = append(datasources, args[i])
			case "-c", "--context": i++; contexts = append(contexts, args[i])
			case "-H", "--datasource-header": i++; headers = append(headers, args[i])
			case "--plugin": i++; plugins = append(plugins, args[i])
			case "--input-dir": i++; inputDir = args[i]
			case "--output-dir": i++; outputDir = args[i]
			case "--output-map": i++; outputMap = args[i]
			case "--missing-key": i++; missingKey = args[i]
			}
		}
		if arg == "-v" || arg == "--version" {
			fmt.Println("gomplate version 0.0.0")
			return
		}
