	for _, dsStr := range datasources {
		parts := strings.SplitN(dsStr, "=", 2)
		if len(parts) == 2 { dsMap[parts[0]] = parts[1] }
	}

	dsHeaders := make(map[string]map[string]string)
	for _, hStr := range headers {
		parts := strings.SplitN(hStr, "=", 2)
		if len(parts) == 2 {
			alias := parts[0]
			headerParts := strings.SplitN(parts[1], ":", 2)
			if len(headerParts) == 2 {
				if dsHeaders[alias] == nil { dsHeaders[alias] = make(map[string]string) }
				dsHeaders[alias][strings.TrimSpace(headerParts[0])] = strings.TrimSpace(headerParts[1])
			}
		}
	}

	ctxMap := make(map[string]interface{})
	envMap := make(map[string]string)
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 { envMap[parts[0]] = parts[1] }
	}
	ctxMap["Env"] = envMap

	funcMap := createFuncMap(dsMap, dsHeaders)
	for _, pStr := range plugins {
		parts := strings.SplitN(pStr, "=", 2)
		if len(parts) == 2 {
			name, path := parts[0], parts[1]
			funcMap[name] = func(args ...interface{}) (string, error) {
				sArgs := make([]string, len(args))
				for i, a := range args { sArgs[i] = fmt.Sprint(a) }
				cmd := exec.Command(path, sArgs...)
