	}

	for _, cStr := range contexts {
		parts := strings.SplitN(cStr, "=", 2)
		if len(parts) == 2 {
			alias, url := parts[0], parts[1]
			data, _ := readDatasource(url, dsHeaders[alias])
			parsedData := parseData(url, data)
			if alias == "." {
				if m, ok := parsedData.(map[string]interface{}); ok {
					for k, v := range m { ctxMap[k] = v }
				}
