func createFuncMap(dsMap map[string]string, dsHeaders map[string]map[string]string) template.FuncMap {
	return template.FuncMap{
		"ds": func(alias string) (interface{}, error) {
			url, ok := dsMap[alias]
			if !ok { return nil, fmt.Errorf("datasource '%s' not found", alias) }
			data, err := readDatasource(url, dsHeaders[alias])
			if err != nil { return nil, err }
			return parseData(url, data), nil
		},
		"json": func(in string) (interface{}, error) {
			var res interface{}; err := json.Unmarshal([]byte(in), &res); return res, err
		},
		"yaml": func(in string) (interface{}, error) {
			var res interface{}; err := json.Unmarshal([]byte(in), &res); return res, err
		},
		"toUpper": strings.ToUpper, "toLower": strings.ToLower,
		"math": func() Math { return Math{} },
		"strings": func() Strings { return Strings{} },
		"net": func() Net { return Net{} },
		"add": add, "mul": mul, "sub": sub, "div": div, "rem": rem, "pow": pow,
		"seq": func(args ...int64) []int64 { return (Math{}).Seq(args...) },
	}
}

func readDatasource(url string, headers map[string]string) ([]byte, error) {
	if strings.HasPrefix(url, "http://") || strings.HasPrefix(url, "https://") {
		client := &http.Client{}
		req, _ := http.NewRequest("GET", url, nil)
		for k, v := range headers { req.Header.Add(k, v) }
		resp, err := client.Do(req)
		if err != nil { return nil, err }
		defer resp.Body.Close()
		return ioutil.ReadAll(resp.Body)
	}
	if strings.HasPrefix(url, "env:") { return []byte(os.Getenv(strings.TrimPrefix(url, "env:"))), nil }
	if strings.HasPrefix(url, "env:///") { return []byte(os.Getenv(strings.TrimPrefix(url, "env:///"))), nil }
	path := strings.TrimPrefix(url, "file://")
	return ioutil.ReadFile(path)
}

func parseData(url string, data []byte) interface{} {
	if strings.HasSuffix(url, ".json") || strings.HasSuffix(url, ".yaml") || strings.HasSuffix(url, ".toml") {
		var res interface{}; json.Unmarshal(data, &res); return res
	}
	return string(data)
}

func render(source, out string, ctx interface{}, funcMap template.FuncMap, missingKey string) error {
	if missingKey == "default" || missingKey == "invalid" { missingKey = "default" }
	tmpl, err := template.New("tmpl").Option("missingkey="+missingKey).Funcs(funcMap).Parse(source)
	if err != nil { return err }
	var w io.Writer = os.Stdout
	if out != "-" {
		f, err := os.Create(out)
		if err != nil { return err }
		defer f.Close()
		w = f
	}
	return tmpl.Execute(w, ctx)
}

func processDir(inputDir, outputDir, outputMap string, ctx interface{}, funcMap template.FuncMap, missingKey string) {
	filepath.Walk(inputDir, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() { return err }
		relPath, _ := filepath.Rel(inputDir, path)
		outPath := filepath.Join(outputDir, relPath)
		if outputMap != "" {
			mappingTmpl, _ := template.New("map").Funcs(funcMap).Parse(outputMap)
			if mappingTmpl != nil {
				var b strings.Builder
				mappingTmpl.Execute(&b, map[string]string{"in": relPath})
				outPath = b.String()
			}
		}
		os.MkdirAll(filepath.Dir(outPath), 0755)
		b, _ := ioutil.ReadFile(path)
		err = render(string(b), outPath, ctx, funcMap, missingKey)
		if err != nil { logError(err) }
		return nil
	})
}

func toFloat(a interface{}) float64 {
	switch v := a.(type) {
	case int: return float64(v)
	case int64: return float64(v)
	case float64: return v
	}
	return 0
}

func add(args ...interface{}) interface{} {
	var f float64; var isF bool
	for _, arg := range args { f += toFloat(arg); if _, ok := arg.(float64); ok { isF = true } }
	if isF { return f }; return int64(f)
}

func mul(args ...interface{}) interface{} {
	var f float64 = 1; var isF bool
	for _, arg := range args { f *= toFloat(arg); if _, ok := arg.(float64); ok { isF = true } }
	if isF { return f }; return int64(f)
}

func sub(args ...interface{}) interface{} {
	if len(args) == 0 { return 0 }
	f := toFloat(args[0]); isF := false
	if _, ok := args[0].(float64); ok { isF = true }
	for _, arg := range args[1:] { f -= toFloat(arg); if _, ok := arg.(float64); ok { isF = true } }
	if isF { return f }; return int64(f)
}

func div(args ...interface{}) float64 {
	if len(args) == 0 { return 0 }
	f := toFloat(args[0])
	for _, arg := range args[1:] { f /= toFloat(arg) }
	return f
}

func rem(a, b interface{}) int64 { return int64(toFloat(a)) % int64(toFloat(b)) }

func pow(a, b interface{}) interface{} {
	res := math.Pow(toFloat(a), toFloat(b))
	if _, ok := a.(float64); ok || isF(b) { return res }
	return int64(res)
}

func isF(a interface{}) bool { _, ok := a.(float64); return ok }
